// src/main.ts
async function readRequiredSecret(filePath, label) {
  const value = (await readFile3(filePath, "utf8")).trim();
  if (!value) throw new Error(`${label} is empty: ${filePath}`);
  return value;
}
var store = createStore();
await store.initialize();
var settingsSecret = await readOrCreateSecret("/srv/cuddly/secrets/settings.key");
var internalApiToken = await readOrCreateSecret("/srv/cuddly/cert-auth/token");
var publicOrigin = normalizePublicOrigin(
  process.env.CUDDLY_PUBLIC_ORIGIN ?? "https://bifrost.vanillacake.cn"
);
var feishuAppId = await readRequiredSecret(
  process.env.CUDDLY_FEISHU_APP_ID_FILE ?? "/srv/cuddly/secrets/feishu/app_id",
  "Feishu app id"
);
var feishuAppSecret = await readRequiredSecret(
  process.env.CUDDLY_FEISHU_APP_SECRET_FILE ?? "/srv/cuddly/secrets/feishu/app_secret",
  "Feishu app secret"
);
var feishuOAuth = new FeishuOAuthClient({
  appId: feishuAppId,
  appSecret: feishuAppSecret,
  redirectUri: feishuCallbackUri(publicOrigin)
});
var proxySettings = new ProxySettingsService({
  store,
  settingsSecret,
  configPath: "/srv/cuddly/secrets/mihomo/config.yaml",
  mihomoConfigPath: "/root/.config/mihomo/config.yaml",
  mihomoControllerUrl: "http://mihomo:9090",
  mihomoControllerSecret: ""
});
await proxySettings.start();
var app = createControlApp({
  store,
  internalApiToken,
  auth: { client: feishuOAuth, publicOrigin },
  proxySettings,
  projectTemplates: PROJECT_TEMPLATES,
  settingsSecret,
  logDirectory: "/srv/cuddly/logs",
  previewBaseDomain: process.env.CUDDLY_PREVIEW_BASE_DOMAIN ?? "bifrost.vanillacake.cn"
});
var server = app.listen(9880, () => console.log("[control-api] listening on 9880"));
async function shutdown() {
  server.close();
  proxySettings.stop();
  await store.close();
}
process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);
